insert into kafaa_oe_lessons (id, title_en, title_ar, summary_en, summary_ar, lesson_en, lesson_ar, source_kind, trait_ids, reviewed_on, reviewing_body, deidentified, status, affected_standard_ids, sample, topic, sources, hu_ids, drill_ids) values
('oe-ai-01', 'Digital twins and predictive maintenance are models of the plant', 'التوائم الرقمية والصيانة التنبؤية نماذج للمحطة', 'The IAEA Bulletin describes digital twins as AI-enhanced tools that analyse plant data to improve operations, and predictive maintenance as relying on digital replicas of real facilities.', 'تصف نشرة الوكالة الدولية للطاقة الذرية التوائم الرقمية بأنها أدوات معززة بالذكاء الاصطناعي تحلل بيانات المحطة لتحسين التشغيل، وتصف الصيانة التنبؤية بأنها تعتمد على نسخ رقمية من المنشآت الفعلية.', 'A twin or advisor is a model of the plant, not the plant: confirm its recommendation against plant indications and the controlled documents before you act on it.', 'التوأم أو المستشار نموذج للمحطة وليس المحطة نفسها: تحقق من توصيته مقابل مؤشرات المحطة والوثائق الخاضعة للرقابة قبل أن تتصرف بناءً عليها.', 'IAEA', array['trait-2','trait-5']::text[], '2026-10-10', 'OE Screening Committee', true, 'published', '{}'::text[], false, 'ai_automation', '[{"label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","year":2025,"as_of":"2026-10-10"}]'::jsonb, array['hu-ai-bias','hu-ai-verify','hu-1']::text[], array['ad-mov-pm','ad-valve-lineup']::text[]),
('oe-ai-02', 'AI is arriving across the nuclear industry', 'الذكاء الاصطناعي يدخل قطاع الطاقة النووية بأكمله', 'The IAEA held its first symposium on AI and nuclear energy at its Vienna headquarters, framed as "Atoms for Algorithms" (reported December 2025).', 'عقدت الوكالة الدولية للطاقة الذرية أول ندوة لها عن الذكاء الاصطناعي والطاقة النووية في مقرها بفيينا تحت شعار «الذرّات من أجل الخوارزميات» (بحسب تقرير ديسمبر 2025).', 'Treat a new AI tool as a change to how work is done: brief it, train people on it, and keep the duty to challenge its output with the person doing the work.', 'تعامل مع أداة الذكاء الاصطناعي الجديدة كتغيير في طريقة العمل: قدّم لها إحاطة، ودرّب الناس عليها، وأبقِ واجب الاعتراض على مخرجاتها لدى من يؤدي العمل.', 'IAEA', array['trait-4','trait-7']::text[], '2026-10-10', 'OE Screening Committee', true, 'published', '{}'::text[], false, 'ai_automation', '[{"label":"NEI Magazine · IAEA hosts first AI nuclear symposium","url":"https://www.neimagazine.com/news/iaea-hosts-first-ai-nuclear-symposium/","year":2025,"as_of":"2026-10-10"}]'::jsonb, array['hu-ai-mode','hu-4']::text[], '{}'::text[]),
('oe-ai-03', 'Questioning an output is a behaviour that can be observed', 'التساؤل عن المخرَج سلوك يمكن ملاحظته', 'IAEA-TECDOC-1917 (2020) gives nuclear organisations methods to assess behavioural competencies, including structured interviews, simulation observation, 360-degree feedback and situational judgement.', 'تقدّم الوثيقة التقنية IAEA-TECDOC-1917 (2020) للمنظمات النووية أساليب لتقييم الكفاءات السلوكية، منها المقابلات المنظمة وملاحظة المحاكاة والتغذية الراجعة الشاملة والحكم الظرفي.', 'Challenging an AI output is part of a questioning attitude: practise it in situational-judgement practice and AI drills, and expect it to be observed in simulator debriefs.', 'الاعتراض على مخرَج الذكاء الاصطناعي جزء من موقف التساؤل: تدرّب عليه في تمارين الحكم الظرفي وتمارين الذكاء الاصطناعي، وتوقّع أن يُلاحَظ في جلسات المراجعة بعد المحاكاة.', 'IAEA', array['trait-2','trait-5']::text[], '2026-10-10', 'OE Screening Committee', true, 'published', '{}'::text[], false, 'ai_automation', '[{"label":"IAEA-TECDOC-1917 · Assessing Behavioural Competencies of Employees in Nuclear Facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","year":2020,"as_of":"2026-10-10"}]'::jsonb, array['hu-5','hu-ai-bias']::text[], array['ad-shift-turnover']::text[]),
('oe-ai-04', 'AI literacy goes with every system people use', 'الإلمام بالذكاء الاصطناعي يرافق كل نظام يستخدمه الناس', 'Article 4 of the EU AI Act, in application since 2 February 2025, asks providers and deployers of AI systems to ensure a sufficient level of AI literacy among the staff who use them. It does not bind ENEC; Kafa''a uses it as a voluntary international reference.', 'تطلب المادة 4 من قانون الذكاء الاصطناعي الأوروبي، السارية منذ 2 فبراير 2025، من مزوّدي أنظمة الذكاء الاصطناعي ومستخدميها ضمان مستوى كافٍ من الإلمام بالذكاء الاصطناعي لدى الموظفين الذين يستخدمونها. وهي لا تُلزم ENEC، وتستخدمها كفاءة مرجعاً دولياً طوعياً.', 'Before you rely on a tool''s output, know what that tool is approved for and complete the literacy measure listed for it in the AI-literacy register.', 'قبل أن تعتمد على مخرَج أداة، اعرف ما اعتُمدت له تلك الأداة وأكمل إجراء الإلمام المدرج لها في سجل الإلمام بالذكاء الاصطناعي.', 'EU AI Office', array['trait-1']::text[], '2026-10-10', 'OE Screening Committee', true, 'published', '{}'::text[], false, 'ai_automation', '[{"label":"European Commission · Repository of AI literacy practices (AI Act Article 4)","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","year":2025,"as_of":"2026-10-10"}]'::jsonb, array['hu-ai-verify','hu-3','hu-4']::text[], '{}'::text[]),
('oe-ai-05', 'Completing a course is not the same as safe use', 'إتمام دورة لا يعني الاستخدام الآمن', 'The European Commission states that replicating the practices in its living repository of AI literacy practices does not automatically grant presumption of compliance with Article 4.', 'تنص المفوضية الأوروبية على أن تكرار الممارسات الواردة في مستودعها الحي لممارسات الإلمام بالذكاء الاصطناعي لا يمنح تلقائياً افتراض الامتثال للمادة 4.', 'A completion record shows that training happened, not that a person uses a tool safely: show it in the work, in drills, peer checks and observed practice.', 'يُثبت سجل الإتمام أن التدريب حدث، لا أن الشخص يستخدم الأداة بأمان: أظهِر ذلك في العمل وفي التمارين وتحقق الزملاء والممارسة الملاحَظة.', 'EU AI Office', array['trait-1','trait-7']::text[], '2026-10-10', 'OE Screening Committee', true, 'published', '{}'::text[], false, 'ai_automation', '[{"label":"European Commission · Repository of AI literacy practices (page updated July 2026)","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","year":2026,"as_of":"2026-10-10"}]'::jsonb, array['hu-ai-reliance','hu-7']::text[], array['ad-rwp-briefing']::text[]),
('oe-ai-06', 'Keep a human-centred mindset', 'حافظ على عقلية تتمحور حول الإنسان', 'UNESCO''s AI competency frameworks (2024) place a human-centred mindset and the ethics of AI alongside AI techniques and system design, with progression from understanding to applying and creating.', 'تضع أطر كفاءات الذكاء الاصطناعي لدى اليونسكو (2024) العقلية المتمحورة حول الإنسان وأخلاقيات الذكاء الاصطناعي إلى جانب تقنيات الذكاء الاصطناعي وتصميم أنظمته، مع تدرّج من الفهم إلى التطبيق والإبداع.', 'The person stays accountable for a decision a tool informed: keep human judgement and the ethics of use ahead of convenience.', 'يبقى الشخص مسؤولاً عن القرار الذي دعمته أداة: قدّم الحكم البشري وأخلاقيات الاستخدام على السهولة.', 'UNESCO', array['trait-1','trait-5']::text[], '2026-10-10', 'OE Screening Committee', true, 'published', '{}'::text[], false, 'ai_automation', '[{"label":"UNESCO AI competency frameworks (GCED Clearinghouse record)","url":"https://gcedclearinghouse.org/en/node/146447","year":2024,"as_of":"2026-10-10"}]'::jsonb, array['hu-ai-reliance']::text[], '{}'::text[]),
('oe-ai-07', 'Know where a tool''s capability ends', 'اعرف أين تنتهي قدرة الأداة', 'The OECD AI Capability Indicators (2025) rate what AI systems can do across capability dimensions such as language, problem solving and metacognition, on a five-level scale, so it can be compared with what a task requires of people.', 'تقيّم مؤشرات قدرات الذكاء الاصطناعي لدى منظمة التعاون الاقتصادي والتنمية (2025) ما تستطيع أنظمة الذكاء الاصطناعي فعله عبر أبعاد قدرات مثل اللغة وحل المشكلات وما وراء المعرفة، على مقياس من خمسة مستويات، لمقارنته بما تتطلبه المهمة من الإنسان.', 'A tool that is strong with language can still be weak at judgement: match how hard you check to the gap between what the task needs and what the tool can do.', 'قد تكون الأداة قوية في اللغة وضعيفة في الحكم: اجعل مقدار تحققك على قدر الفجوة بين ما تتطلبه المهمة وما تستطيعه الأداة.', 'OECD', array['trait-2']::text[], '2026-10-10', 'OE Screening Committee', true, 'published', '{}'::text[], false, 'ai_automation', '[{"label":"OECD AI Capability Indicators · technical report","url":"https://digital-skills-jobs.europa.eu/en/latest/research/oecd-ai-capability-indicators-technical-report","year":2025,"as_of":"2026-10-10"}]'::jsonb, array['hu-ai-mode']::text[], array['ad-requisition-qa']::text[])
insert into kafaa_cec_competences (id, code, area, name_en, name_ar, summary_en, summary_ar, plant_en, plant_ar, outcomes, greencomp_area, skill_ids, learning, jahiz_group, net_zero, benchmark_ids, sources, status, version, as_of, sort) values
('cec-1-1', 'CEC-1.1', 'values', 'Public trust and transparency', 'الثقة العامة والشفافية', 'Explains nuclear energy''s place in a low-carbon energy system honestly, with the evidence and its limits, so people can judge for themselves.', 'يشرح مكانة الطاقة النووية في منظومة طاقة منخفضة الكربون بأمانة، بالأدلة وحدودها، ليحكم الناس بأنفسهم.', 'At a nuclear plant this means answering questions about emissions, safety and waste with sourced facts, never with slogans.', 'في المحطة النووية يعني ذلك الإجابة عن أسئلة الانبعاثات والسلامة والنفايات بحقائق موثّقة المصدر، لا بالشعارات.', '[{"en":"Explain in plain language why nuclear electricity is low-carbon over its lifecycle, and where the evidence comes from.","ar":"يشرح بلغة بسيطة لماذا تُعدّ الكهرباء النووية منخفضة الكربون على امتداد دورة حياتها، ومن أين تأتي الأدلة."},{"en":"Answer a difficult public question about safety or waste with sourced facts, and say what is not known.","ar":"يجيب عن سؤال عام صعب حول السلامة أو النفايات بحقائق موثّقة المصدر، ويذكر ما لا يزال غير معروف."},{"en":"Recognise when a claim about clean energy goes beyond the evidence, and correct it respectfully.","ar":"يتعرّف على الادعاء الذي يتجاوز الأدلة بشأن الطاقة النظيفة ويصححه باحترام."}]'::jsonb, 'embodying_sustainability_values', array['sk-fs-gr-esg','sk-fs-tr-empathy','sk-sc-01']::text[], '[{"kind":"pathway","ref":"pw-gr-esg-l1","title_en":"ESG disclosure literacy: foundations","title_ar":"الإلمام بالإفصاح البيئي والاجتماعي والحوكمي: الأساسيات"},{"kind":"external","ref":"xr-et-greencomp","title_en":"GreenComp: the European sustainability competence framework","title_ar":"إطار \"غرين كومب\": الإطار الأوروبي لكفاءات الاستدامة"},{"kind":"course","ref":"c-fs-ghg","title_en":"GHG accounting basics","title_ar":"أساسيات محاسبة غازات الدفيئة"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 1),
('cec-1-2', 'CEC-1.2', 'values', 'Stewardship of people and the environment', 'رعاية الناس والبيئة', 'Treats protecting people and the environment as part of the job, from radiation protection to effluent monitoring.', 'يعدّ حماية الناس والبيئة جزءاً من العمل، من الوقاية من الإشعاع إلى رصد المخلفات السائلة والغازية.', 'Radiation protection, chemistry and environmental monitoring teams already live this every day; everyone else learns why it matters.', 'تعيش فرق الوقاية من الإشعاع والكيمياء والرصد البيئي هذه الكفاءة يومياً؛ ويتعلّم الآخرون سبب أهميتها.', '[{"en":"Describe how radiation protection and effluent monitoring protect people and the environment around a plant.","ar":"يصف كيف تحمي الوقاية من الإشعاع ورصد المخلفات الناس والبيئة حول المحطة."},{"en":"Apply ALARA thinking to an everyday task and explain the trade-offs.","ar":"يطبّق مبدأ \"أدنى مستوى يمكن بلوغه عملياً\" على مهمة يومية ويشرح الموازنات."},{"en":"Report an environmental concern through the right channel without delay.","ar":"يبلّغ عن أي مخاوف بيئية عبر القناة الصحيحة دون تأخير."}]'::jsonb, 'embodying_sustainability_values', array['sk-fs-tr-environment','sk-rp-02','sk-ch-02','sk-sc-02']::text[], '[{"kind":"pathway","ref":"pw-tr-environment-l1","title_en":"Environmental stewardship: foundations","title_ar":"الإشراف البيئي: الأساسيات"},{"kind":"external","ref":"xr-uncclearn-climate","title_en":"Introductory e-Course on Climate Change","title_ar":"المقرر الإلكتروني التمهيدي حول تغير المناخ"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 2),
('cec-1-3', 'CEC-1.3', 'values', 'Fairness across generations', 'العدالة بين الأجيال', 'Weighs today''s decisions against the people who will run, use and inherit the plant over its long life.', 'يوازن قرارات اليوم مع مصلحة من سيشغّلون المحطة ويستفيدون منها ويرثونها على امتداد عمرها الطويل.', 'A nuclear plant runs for decades: fuel, waste and knowledge decisions made now are inherited by the next generation of staff.', 'تعمل المحطة النووية لعقود: قرارات الوقود والنفايات والمعرفة المتخذة اليوم يرثها الجيل القادم من العاملين.', '[{"en":"Explain why decisions on fuel, waste and knowledge affect people decades from now.","ar":"يشرح لماذا تؤثّر قرارات الوقود والنفايات والمعرفة في أناس بعد عقود."},{"en":"Pass on what you know so that the next generation can operate safely.","ar":"ينقل ما يعرفه ليتمكّن الجيل القادم من التشغيل بأمان."},{"en":"Take account of future users when choosing between short-term and long-term options.","ar":"يراعي المستخدمين في المستقبل عند الاختيار بين الخيارات قصيرة الأجل وطويلة الأجل."}]'::jsonb, 'embodying_sustainability_values', array['sk-fs-gr-circular','sk-fs-tr-crosscultural','sk-ld-01-coach']::text[], '[{"kind":"pathway","ref":"pw-gr-circular-l1","title_en":"Circularity and waste stewardship: foundations","title_ar":"الاقتصاد الدائري والإشراف على النفايات: الأساسيات"},{"kind":"lane","ref":"lane-netzero","title_en":"Net zero and low-carbon industry","title_ar":"الحياد المناخي والصناعة منخفضة الكربون"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 3),
('cec-2-1', 'CEC-2.1', 'complexity', 'Systems thinking under uncertainty', 'التفكير المنظومي في ظل عدم اليقين', 'Sees the energy system, the plant and its people as connected parts, and reasons about effects that are delayed, shared or uncertain.', 'يرى منظومة الطاقة والمحطة والعاملين فيها أجزاءً مترابطة، ويستدل على الآثار المتأخرة أو المشتركة أو غير المؤكدة.', 'Defence in depth is a systems idea: the same habit of mind helps when thinking about energy security and the wider grid.', 'الدفاع في العمق فكرة منظومية: والعادة الذهنية نفسها تساعد عند التفكير في أمن الطاقة والشبكة الأوسع.', '[{"en":"Map how a change in one part of the energy system affects others, including feedback and delays.","ar":"يرسم كيف يؤثّر تغيير في جزء من منظومة الطاقة في الأجزاء الأخرى، بما في ذلك التغذية الراجعة والتأخير."},{"en":"Explain defence in depth as a systems idea and relate it to energy security.","ar":"يشرح الدفاع في العمق بوصفه فكرة منظومية ويربطه بأمن الطاقة."},{"en":"State the uncertainty in a forecast or plan and what would change your view.","ar":"يحدّد عدم اليقين في توقّع أو خطة وما الذي قد يغيّر رأيه."}]'::jsonb, 'embracing_complexity_in_sustainability', array['sk-fs-tr-systems','sk-ns-01','sk-ld-02-decide']::text[], '[{"kind":"course","ref":"c-fs-systems","title_en":"Systems thinking","title_ar":"التفكير المنظومي"},{"kind":"external","ref":"xr-openlearn-systems","title_en":"Mastering systems thinking in practice","title_ar":"إتقان التفكير المنظومي في الممارسة"},{"kind":"pathway","ref":"pw-tr-systems-l1","title_en":"Systems thinking: foundations","title_ar":"التفكير المنظومي: الأساسيات"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 4),
('cec-2-2', 'CEC-2.2', 'complexity', 'Lifecycle carbon thinking', 'التفكير في الكربون على امتداد دورة الحياة', 'Counts emissions across the whole life of a plant or activity, from construction and fuel to operation and decommissioning.', 'يحسب الانبعاثات على امتداد عمر المحطة أو النشاط كاملاً، من الإنشاء والوقود إلى التشغيل والإيقاف النهائي.', 'Lifecycle thinking lets a team compare options honestly, including the emissions of maintenance, travel and purchased goods.', 'يتيح التفكير في دورة الحياة للفريق مقارنة الخيارات بأمانة، بما في ذلك انبعاثات الصيانة والسفر والسلع المشتراة.', '[{"en":"Classify emissions by scope and explain an emissions-avoided figure.","ar":"يصنّف الانبعاثات حسب النطاق ويشرح رقم الانبعاثات التي تم تجنّبها."},{"en":"Outline a lifecycle carbon assessment for a plant activity.","ar":"يضع مخططاً لتقييم الكربون على امتداد دورة الحياة لنشاط في المحطة."},{"en":"Explain why lifecycle numbers differ between studies and which assumptions drive them.","ar":"يشرح لماذا تختلف أرقام دورة الحياة بين الدراسات وما الافتراضات التي تحرّكها."}]'::jsonb, 'embracing_complexity_in_sustainability', array['sk-fs-gr-lifecycle','sk-fs-gr-ghg']::text[], '[{"kind":"course","ref":"c-fs-ghg","title_en":"GHG accounting basics","title_ar":"أساسيات محاسبة غازات الدفيئة"},{"kind":"adaptive","ref":"ab-clean-energy","title_en":"CleanEnergyComp foundations","title_ar":"أسس كفاءات الطاقة النظيفة"},{"kind":"task","ref":"pt-ghg-log","title_en":"Green: the fuel log that does not add up","title_ar":"أخضر: سجل الوقود الذي لا يستقيم"},{"kind":"credential","ref":"MC-CLEAN-ENERGY","title_en":"Clean energy systems","title_ar":"أنظمة الطاقة النظيفة"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 5),
('cec-2-3', 'CEC-2.3', 'complexity', 'Critical use of evidence and data', 'الاستخدام النقدي للأدلة والبيانات', 'Checks the quality of data and claims before using them in a sustainability decision or report.', 'يتحقق من جودة البيانات والادعاءات قبل استخدامها في قرار أو تقرير يخص الاستدامة.', 'The same discipline that keeps plant data trustworthy keeps sustainability figures trustworthy: source, scope, date.', 'الانضباط نفسه الذي يحفظ موثوقية بيانات المحطة يحفظ موثوقية أرقام الاستدامة: المصدر والنطاق والتاريخ.', '[{"en":"Test a sustainability figure for its source, scope and date before repeating it.","ar":"يختبر رقماً يخص الاستدامة من حيث مصدره ونطاقه وتاريخه قبل تكراره."},{"en":"Spot gaps and double counting in an emissions or resource data set.","ar":"يكتشف الثغرات والعدّ المزدوج في مجموعة بيانات للانبعاثات أو الموارد."},{"en":"Present a conclusion with its evidence and its limits.","ar":"يعرض استنتاجاً مع أدلته وحدوده."}]'::jsonb, 'embracing_complexity_in_sustainability', array['sk-fs-tr-analytical','sk-fs-ai-plantdata','sk-da-01-analysis']::text[], '[{"kind":"task","ref":"pt-ghg-log","title_en":"Green: the fuel log that does not add up","title_ar":"أخضر: سجل الوقود الذي لا يستقيم"},{"kind":"course","ref":"c-et-ghg-mgr","title_en":"GHG and ESG basics for managers","title_ar":"أساسيات غازات الدفيئة والحوكمة البيئية والاجتماعية للمديرين"},{"kind":"pathway","ref":"pw-et-esg-managers","title_en":"ESG and GHG literacy for managers","title_ar":"الإلمام بالحوكمة البيئية والاجتماعية وغازات الدفيئة للمديرين"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 6),
('cec-3-1', 'CEC-3.1', 'futures', 'Net-zero pathways literacy', 'الإلمام بمسارات الحياد الصفري', 'Understands how countries and industries plan to reach net zero, and the part low-carbon electricity plays.', 'يفهم كيف تخطط الدول والصناعات لبلوغ الحياد الصفري، والدور الذي تؤديه الكهرباء منخفضة الكربون.', 'Linked to the UAE Net Zero 2050 strategic initiative and to the New Economy group of the federal Jahiz future-skills platform.', 'مرتبطة بالمبادرة الاستراتيجية للحياد المناخي 2050 في الإمارات، وبمجموعة مهارات الاقتصاد الجديد في منصة "جاهز" الاتحادية لمهارات المستقبل.', '[{"en":"Describe the main levers of a net-zero pathway: clean power, efficiency, electrification and low-carbon fuels.","ar":"يصف الروافع الرئيسية لمسار الحياد الصفري: الطاقة النظيفة والكفاءة والكهربة والوقود منخفض الكربون."},{"en":"Explain climate risk to the plant and its users in simple terms.","ar":"يشرح المخاطر المناخية على المحطة ومستخدميها بعبارات بسيطة."},{"en":"Relate the national net-zero goal to your own work and your team.","ar":"يربط الهدف الوطني للحياد الصفري بعمله وبفريقه."}]'::jsonb, 'envisioning_sustainable_futures', array['sk-fs-gr-climaterisk','sk-fs-gr-ghg']::text[], '[{"kind":"external","ref":"xr-uncclearn-climate","title_en":"Introductory e-Course on Climate Change","title_ar":"المقرر الإلكتروني التمهيدي حول تغير المناخ"},{"kind":"lane","ref":"lane-netzero","title_en":"Net zero and low-carbon industry","title_ar":"الحياد المناخي والصناعة منخفضة الكربون"},{"kind":"pathway","ref":"pw-gr-climaterisk-l1","title_en":"Climate risk awareness: foundations","title_ar":"الوعي بمخاطر المناخ: الأساسيات"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 7),
('cec-3-2', 'CEC-3.2', 'futures', 'The role of nuclear in an integrated energy system', 'دور الطاقة النووية في منظومة طاقة متكاملة', 'Explains how nuclear power and heat could work with renewables, storage, hydrogen and industry. Concept learning; no deployment decision implied.', 'يشرح كيف يمكن للكهرباء والحرارة النوويتين العمل مع الطاقة المتجددة والتخزين والهيدروجين والصناعة. تعلّم مفاهيمي، ولا يُفهم منه أي قرار بالنشر.', 'Steady low-carbon output complements variable renewables; heat and power could also serve hydrogen and industrial users.', 'يكمّل الإنتاج الثابت منخفض الكربون الطاقة المتجددة المتغيرة؛ ويمكن للحرارة والكهرباء أيضاً خدمة مستخدمي الهيدروجين والصناعة.', '[{"en":"Explain how steady nuclear output complements variable renewables on the grid.","ar":"يشرح كيف يكمّل الإنتاج النووي الثابت الطاقة المتجددة المتغيرة على الشبكة."},{"en":"Describe how nuclear heat and electricity could serve hydrogen and industrial users, and where the safety boundary sits.","ar":"يصف كيف يمكن للحرارة والكهرباء النوويتين خدمة مستخدمي الهيدروجين والصناعة، وأين تقع حدود السلامة."},{"en":"Compare the hydrogen, process-heat and grid value chains and the skills each needs.","ar":"يقارن سلاسل القيمة للهيدروجين والحرارة الصناعية والشبكة والمهارات التي تحتاجها كل منها."}]'::jsonb, 'envisioning_sustainable_futures', array['sk-fs-gr-h2heat','sk-fs-gr-grid','sk-pf-02','sk-pf-03-elec']::text[], '[{"kind":"chain","ref":"vc-hydrogen","title_en":"Hydrogen","title_ar":"الهيدروجين"},{"kind":"pathway","ref":"pw-et-system-integration","title_en":"Energy-system integration: from awareness to practitioner","title_ar":"تكامل منظومة الطاقة: من الوعي إلى الممارسة"},{"kind":"course","ref":"c-fs-h2heat","title_en":"Hydrogen and process heat","title_ar":"الهيدروجين والحرارة الصناعية"},{"kind":"academy","ref":"ac-energy","title_en":"Energy Transition cohort","title_ar":"دفعة التحول في قطاع الطاقة"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 8),
('cec-3-3', 'CEC-3.3', 'futures', 'Exploring new technologies with an open mind', 'استكشاف التقنيات الجديدة بعقل منفتح', 'Approaches advanced reactors and other new energy technologies with curiosity and sound judgement, separating what is known from what is promoted.', 'يتعامل مع المفاعلات المتقدمة وتقنيات الطاقة الجديدة الأخرى بفضول وحكم سليم، فيفصل بين ما هو معروف وما يُروَّج له.', 'Advanced reactor families are evaluated as concepts; curiosity and evidence keep that learning honest.', 'تُقيَّم عائلات المفاعلات المتقدمة بوصفها مفاهيم؛ ويحافظ الفضول والأدلة على أمانة هذا التعلّم.', '[{"en":"Describe the main advanced reactor families and what changes for the people who run them.","ar":"يصف العائلات الرئيسية للمفاعلات المتقدمة وما يتغيّر لمن يشغّلونها."},{"en":"Separate evidence from promotion in claims about a new energy technology.","ar":"يفصل بين الأدلة والترويج في الادعاءات المتعلقة بتقنية طاقة جديدة."},{"en":"Adapt how you work when a new technology or method arrives.","ar":"يكيّف طريقة عمله عند ظهور تقنية أو أسلوب جديد."}]'::jsonb, 'envisioning_sustainable_futures', array['sk-fs-adv-smr','sk-fs-tr-curiosity','sk-fs-tr-resilience']::text[], '[{"kind":"course","ref":"c-adv-intro","title_en":"Advanced reactor families: an orientation","title_ar":"عائلات المفاعلات المتقدمة: مدخل تعريفي"},{"kind":"adaptive","ref":"ab-smr","title_en":"SMR fundamentals","title_ar":"أساسيات المفاعلات المعيارية الصغيرة"},{"kind":"lane","ref":"lane-advanced","title_en":"Advanced reactor fundamentals","title_ar":"أساسيات المفاعلات المتقدمة"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 9),
('cec-4-1', 'CEC-4.1', 'acting', 'Waste stewardship', 'رعاية النفايات', 'Minimises, tracks and safely manages waste and effluents, from daily work to the back end of the fuel cycle.', 'يقلّل النفايات والمخلفات ويتتبعها ويديرها بأمان، من العمل اليومي إلى المرحلة الختامية من دورة الوقود.', 'Every work package can create less radioactive and conventional waste when it is planned with the waste hierarchy in mind.', 'يمكن لكل حزمة عمل أن تُنتج نفايات مشعة وتقليدية أقل عندما تُخطَّط مع مراعاة هرم إدارة النفايات.', '[{"en":"Explain the waste hierarchy and how it applies to plant work.","ar":"يشرح هرم إدارة النفايات وكيف ينطبق على العمل في المحطة."},{"en":"Plan a task so that it creates less radioactive and conventional waste.","ar":"يخطط لمهمة بحيث تُنتج نفايات مشعة وتقليدية أقل."},{"en":"Describe, as a concept, how spent fuel and radioactive waste are kept safe over the long term.","ar":"يصف، بوصفه مفهوماً، كيف يُحافَظ على سلامة الوقود المستهلك والنفايات المشعة على المدى الطويل."}]'::jsonb, 'acting_for_sustainability', array['sk-fs-gr-circular','sk-ch-02','sk-rp-02-survey']::text[], '[{"kind":"opportunity","ref":"fg-kc-waste-minimisation","title_en":"Knowledge capture: waste-minimisation good practice","title_ar":"التقاط المعرفة: الممارسات الجيدة لتقليل النفايات"},{"kind":"pathway","ref":"pw-gr-circular-l1","title_en":"Circularity and waste stewardship: foundations","title_ar":"الاقتصاد الدائري والإشراف على النفايات: الأساسيات"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 10),
('cec-4-2', 'CEC-4.2', 'acting', 'Circularity and resource efficiency', 'الاقتصاد الدائري وكفاءة الموارد', 'Keeps equipment, materials and data in use for longer, and buys with the whole life in mind.', 'يُبقي المعدات والمواد والبيانات قيد الاستخدام مدة أطول، ويشتري مع مراعاة دورة الحياة كاملة.', 'Maintenance, engineering and supply chain decide together when to repair, refurbish or replace.', 'تقرر الصيانة والهندسة وسلسلة الإمداد معاً متى يكون الإصلاح أو التجديد أو الاستبدال.', '[{"en":"Identify where repair, refurbishment or reuse can replace replacement in maintenance work.","ar":"يحدّد أين يمكن للإصلاح أو التجديد أو إعادة الاستخدام أن يحلّ محل الاستبدال في أعمال الصيانة."},{"en":"Include lifecycle and end-of-life questions when specifying or buying equipment.","ar":"يضمّن أسئلة دورة الحياة ونهاية العمر عند تحديد مواصفات المعدات أو شرائها."},{"en":"Use condition data to extend the useful life of a component safely.","ar":"يستخدم بيانات الحالة لإطالة العمر النافع لمكوّن بأمان."}]'::jsonb, 'acting_for_sustainability', array['sk-fs-gr-circular','sk-fs-dp-procurement','sk-en-02']::text[], '[{"kind":"pathway","ref":"pw-gr-circular-l2","title_en":"Circularity and waste stewardship: practitioner","title_ar":"الاقتصاد الدائري والإشراف على النفايات: الممارسة"},{"kind":"opportunity","ref":"fg-kc-waste-minimisation","title_en":"Knowledge capture: waste-minimisation good practice","title_ar":"التقاط المعرفة: الممارسات الجيدة لتقليل النفايات"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 11),
('cec-4-3', 'CEC-4.3', 'acting', 'Advocacy with evidence', 'المناصرة بالأدلة', 'Speaks up for sustainable choices inside and outside the organisation, always with evidence and respect for other views.', 'يدافع عن الخيارات المستدامة داخل المؤسسة وخارجها، دائماً بالأدلة ومع احترام الآراء الأخرى.', 'Managers and communicators carry this most: they turn data into a fair account of progress, including what went less well.', 'يحمل المديرون والمختصون بالتواصل هذه الكفاءة أكثر من غيرهم: يحوّلون البيانات إلى عرض منصف للتقدم، بما في ذلك ما لم يسر على ما يرام.', '[{"en":"Make a short, sourced case for a sustainability improvement in your team.","ar":"يقدّم حجة قصيرة موثّقة المصدر لتحسين يخص الاستدامة في فريقه."},{"en":"Disclose sustainability information clearly, including what went less well.","ar":"يفصح عن معلومات الاستدامة بوضوح، بما في ذلك ما لم يسر على ما يرام."},{"en":"Lead or join a team effort that measurably reduces the use of a resource.","ar":"يقود جهداً جماعياً أو يشارك فيه يقلّل استخدام أحد الموارد بشكل قابل للقياس."}]'::jsonb, 'acting_for_sustainability', array['sk-fs-gr-esg','sk-fs-tr-leadership','sk-ld-01']::text[], '[{"kind":"pathway","ref":"pw-et-esg-managers","title_en":"ESG and GHG literacy for managers","title_ar":"الإلمام بالحوكمة البيئية والاجتماعية وغازات الدفيئة للمديرين"},{"kind":"course","ref":"c-et-esg-clinic","title_en":"ESG data clinic: your team''s numbers","title_ar":"عيادة بيانات الحوكمة البيئية والاجتماعية: أرقام فريقك"},{"kind":"credential","ref":"MC-CLEAN-ENERGY","title_en":"Clean energy systems","title_ar":"أنظمة الطاقة النظيفة"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 12)
insert into kafaa_cec_role_targets (id, family_id, level, focus_ids, rationale_en, rationale_ar) values
('cect:operations', 'operations', 1, array['cec-1-2','cec-2-1']::text[], 'Operators steward people and the environment every shift and think in systems; awareness level across all four areas.', 'يرعى المشغّلون الناس والبيئة في كل وردية ويفكرون بطريقة منظومية؛ مستوى الوعي في المجالات الأربعة.'),
('cect:maintenance', 'maintenance', 1, array['cec-4-2','cec-4-1']::text[], 'Maintenance decides daily between repair and replacement and creates most work-package waste.', 'تقرر الصيانة يومياً بين الإصلاح والاستبدال، وتُنتج معظم نفايات حزم العمل.'),
('cect:engineering', 'engineering', 2, array['cec-3-2','cec-2-2','cec-4-2']::text[], 'Engineers assess lifecycle impacts and would carry the technical work on any energy-system interface.', 'يقيّم المهندسون آثار دورة الحياة، وسيحملون العمل الفني لأي واجهة مع منظومة الطاقة.'),
('cect:radiation-protection', 'radiation-protection', 2, array['cec-1-2','cec-4-1']::text[], 'Radiation protection leads stewardship of people and the environment and the control of radioactive waste.', 'تقود الوقاية من الإشعاع رعاية الناس والبيئة وضبط النفايات المشعة.'),
('cect:chemistry', 'chemistry', 2, array['cec-4-1','cec-1-2']::text[], 'Chemistry monitors effluents and manages chemical and radioactive waste streams.', 'تراقب الكيمياء المخلفات وتدير مسارات النفايات الكيميائية والمشعة.'),
('cect:nuclear-fuel', 'nuclear-fuel', 2, array['cec-1-3','cec-4-1']::text[], 'Fuel decisions shape the back end of the fuel cycle for decades.', 'تشكّل قرارات الوقود المرحلة الختامية من دورة الوقود لعقود.'),
('cect:outage', 'outage', 1, array['cec-4-2','cec-4-1']::text[], 'Outages concentrate maintenance waste and buying decisions in a few weeks.', 'تتركّز في فترات الانقطاع نفايات الصيانة وقرارات الشراء خلال أسابيع قليلة.'),
('cect:emergency-preparedness', 'emergency-preparedness', 1, array['cec-3-1','cec-2-1']::text[], 'Emergency planning needs a clear view of climate risk and of how systems fail together.', 'يحتاج التخطيط للطوارئ إلى رؤية واضحة للمخاطر المناخية ولكيفية تعطّل الأنظمة معاً.'),
('cect:security', 'security', 1, array['cec-1-1']::text[], 'Awareness level only; the role is shown at career-path level and sustainability content stays general.', 'مستوى الوعي فقط؛ يُعرض الدور على مستوى المسار المهني ويبقى محتوى الاستدامة عاماً.'),
('cect:cyber', 'cyber', 1, array['cec-2-3']::text[], 'Awareness level; the data discipline behind trustworthy figures is the most relevant competence.', 'مستوى الوعي؛ والانضباط في البيانات الذي يقف خلف الأرقام الموثوقة هو الكفاءة الأوثق صلة.'),
('cect:safeguards', 'safeguards', 1, array['cec-1-3']::text[], 'Awareness level; fairness across generations matches the long view of safeguards work.', 'مستوى الوعي؛ وتتوافق العدالة بين الأجيال مع النظرة البعيدة لعمل الضمانات.'),
('cect:quality', 'quality', 1, array['cec-2-3','cec-4-3']::text[], 'Quality staff check data and claims and help disclose them accurately.', 'يتحقق موظفو الجودة من البيانات والادعاءات ويساعدون في الإفصاح عنها بدقة.'),
('cect:oversight', 'oversight', 1, array['cec-2-1','cec-2-3']::text[], 'Oversight challenges assumptions and evidence across the organisation.', 'تتحدى الرقابة الافتراضات والأدلة على مستوى المؤسسة.'),
('cect:licensing', 'licensing', 1, array['cec-1-1','cec-2-1']::text[], 'Licensing explains the plant to external audiences with evidence and its limits.', 'يشرح الترخيص المحطة للجهات الخارجية بالأدلة وحدودها.'),
('cect:training', 'training', 1, array['cec-1-3','cec-4-3']::text[], 'Trainers pass knowledge to the next generation and model evidence-based advocacy.', 'ينقل المدربون المعرفة إلى الجيل القادم ويقدّمون نموذجاً للمناصرة القائمة على الأدلة.'),
('cect:health-safety', 'health-safety', 1, array['cec-1-2','cec-3-1']::text[], 'Health and safety connects stewardship of people with climate risk such as heat stress.', 'تربط الصحة والسلامة رعاية الناس بالمخاطر المناخية مثل الإجهاد الحراري.'),
('cect:environment', 'environment', 3, array['cec-2-2','cec-1-2','cec-4-1']::text[], 'The environment team leads the framework and advises others on lifecycle carbon, stewardship and waste.', 'يقود فريق البيئة الإطار وينصح الآخرين في الكربون على امتداد دورة الحياة والرعاية والنفايات.'),
('cect:supply-chain', 'supply-chain', 2, array['cec-4-2','cec-2-2']::text[], 'Supply chain buys with the whole life in mind and owns much of the purchased-goods footprint.', 'تشتري سلسلة الإمداد مع مراعاة دورة الحياة كاملة، وتملك جزءاً كبيراً من بصمة السلع المشتراة.'),
('cect:fire-protection', 'fire-protection', 1, array['cec-1-2']::text[], 'Fire protection protects people and the environment from fire and its run-off.', 'تحمي الوقاية من الحرائق الناس والبيئة من الحرائق ومخلفاتها.'),
('cect:corporate', 'corporate', 2, array['cec-1-1','cec-4-3','cec-3-1']::text[], 'Communications, sustainability and reporting teams explain and disclose progress, so they need practitioner level.', 'تشرح فرق التواصل والاستدامة وإعداد التقارير التقدّم وتفصح عنه، لذا تحتاج إلى مستوى الممارس.')
